        path = [(start, [])]  # Initialize the recursive path with the start node and an empty path
    if path[-1][0] == goal:
        return path[-1][1]  # If the goal node is reached, return the full path
    node, full_path = path.pop()  # Pop the last node and path from the stack
    for neighbor in graph[node]:
        if neighbor not in [x[0] for x in path]:  # Ensure the neighbor is not already in the path
            path.append((neighbor, full_path + [neighbor]))  # Append the neighbor and its path to the stack
    return find_path(graph, start, goal, path)  # Recursively search for the path

def find_path(graph, start, goal):
    if start is None or goal is None:
        raise ValueError("Neither the start or the goal can be None.')

    if start not in graph and goal not in graph:
        raise ValueError('The given start and goal are not in the graph')

    if start == goal:
        return [start]

    visited = set()
    stack = [[start]]
    while stack:
        path = stack.pop()
        node = path[-1]
        if node not in visited:
            visited.add(node)
            neighbours = graph.get(node, [])
            for neighbour in neighbours:
                new_path = list(path)
                new_path.append(neighbour)
                if neighbour == goal:
                    return new_path
                stack.append(new_path)
    return None

def find_path(graph, start, goal):
    if start == goal:
        return [start]  # If the start and goal are the same, we have a trivial path by just having the start node.
    stack = [(start, [start)]]
    visited = set()
    if start is None or goal is None:
        return None  # Return None if start or goal is None
    while stack:
        (current_node, path) = stack.pop()
        visited.add(current_node)
        for next_node in graph[current_node]:
            if next_node not in visited:
                if next_node == goal:
                    return path + [next_node]
                else:
                    stack.append((next_node, path + [next_node]))
    return None  # Goal is not reachable

